def solve():
    # Read input
    WELL_FORMED = input().strip()
    CHAIN = input().strip()

    # Split the input into tokens
    tokens = WELL_FORMED.split(',')
    chain = []

    # Process each token
    for token in tokens:
        if token == '':
            continue
        if token in CHAIN:
            chain.append(token)
        else:
            # Find the first token that matches the current token
            for i in range(len(chain)):
                if chain[i] == token:
                    break
            else:
                # If no match found, append the current token
                chain.append(token)

    # Output the result
    print(','.join(chain))

